// ── TEST MODE — flip to false when going live ──────────────
const TEST_MODE  = false;
const TEST_EMAIL = 'inder@openmind.in';
// ───────────────────────────────────────────────────────────

const row = $('Loop Over Items').item.json;
const d   = $input.first().json;

const bufStr = v => {
  if (v == null) return '';
  if (typeof v === 'object' && v.type === 'Buffer' && Array.isArray(v.data)) {
    try { return new TextDecoder().decode(new Uint8Array(v.data)); } catch { return ''; }
  }
  return String(v);
};

const complaintno = bufStr(d.complaintno);
const productName = bufStr(d.productname) || 'the reported issue';
const storeName   = bufStr(d.storename)   || '';
const storeCode   = bufStr(d.storecode)   || '';
const storeEmail  = bufStr(d.storeemail)  || '';
const fmEmail     = bufStr(d.fmemail)     || '';
const fmName      = bufStr(d.fmname)      || '';

const closedBy  = (row['Case Closed By'] || '').trim();
const remarks   = (row['Remarks']        || '').trim();
const closureDate = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });

const subject = `Your store ticket ${complaintno} has been Closed`;

const htmlBody = `
<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.7;max-width:600px;margin:0 auto">
  <div style="background:#1e1b4b;padding:18px 28px;border-radius:8px 8px 0 0">
    <div style="color:#a5b4fc;font-size:11px;letter-spacing:.08em;text-transform:uppercase;margin-bottom:2px">VMM Facility Management</div>
    <h2 style="color:#fff;margin:0;font-size:18px">Complaint Closed</h2>
  </div>
  <div style="background:#fff;padding:24px 28px;border:1px solid #e2e8f0;border-top:none">
    <p style="margin:0 0 16px">Dear Store Manager,</p>
    <p style="margin:0 0 20px">
      We are pleased to inform you that your store ticket <strong>${complaintno}</strong> for
      <strong>${productName}</strong> at <strong>${storeName} (${storeCode})</strong>
      has been successfully closed.
      ${fmName && closureDate ? `The same was confirmed by FM <strong>${fmName}</strong> on <strong>${closureDate}</strong>.` : ''}
    </p>
    ${closedBy ? `<p style="margin:0 0 16px">Closed by: <strong>${closedBy}</strong></p>` : ''}
    ${remarks  ? `<p style="margin:0 0 20px;padding:12px 14px;background:#f8fafc;border-left:3px solid #6366f1;font-size:13px"><strong>Remarks:</strong> ${remarks}</p>` : ''}
    <p style="margin:0;font-size:13px;color:#64748b">
      For any queries please reach us at
      <a href="mailto:vmm.helpdesk@openmind.in" style="color:#4f46e5">vmm.helpdesk@openmind.in</a>
      or call <strong>9711 772 722</strong>. Thank you for your cooperation.
    </p>
    <p style="margin:16px 0 0;font-size:13px">Regards,<br/><strong>VMM Helpdesk</strong><br/>9711 772 722</p>
  </div>
  <div style="padding:12px 28px;background:#f8fafc;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 8px 8px;font-size:11px;color:#94a3b8">
    Open Mind Services Limited &nbsp;·&nbsp; VMM CRM &nbsp;·&nbsp; vmm.helpdesk@openmind.in
  </div>
</div>`;

const finalSubject = TEST_MODE ? `[TEST] ${subject}` : subject;
const toEmail  = TEST_MODE ? TEST_EMAIL : storeEmail;
const ccEmails = TEST_MODE ? '' : [fmEmail].filter(Boolean).join(',');

return [{ json: { subject: finalSubject, htmlBody, toEmail, ccEmails, complaintno } }];

// Build a single batchUpdate payload for all pending rows — one API call regardless of count.
// Sheet column order: A=Complaint No, B=Email Subject, C=Case Closed By, D=Remarks, E=Status
const rows = $('Get row(s) in sheet').all();
if (rows.length === 0) {
  return [{ json: { body: JSON.stringify({ valueInputOption: 'USER_ENTERED', data: [] }), count: 0 } }];
}
const data = rows.map(r => ({
  range: `'Close Cases'!E${r.json.row_number}`,
  values: [['Done']]
}));
return [{ json: { body: JSON.stringify({ valueInputOption: 'USER_ENTERED', data }), count: rows.length } }];
